export const NETWORK_CONSTITUTION_TITLE = NETWORK_CONSTITUTION_LOCALES.en.title;
export const NETWORK_CONSTITUTION_STATUS = NETWORK_CONSTITUTION_LOCALES.en.status;
export const NETWORK_CONSTITUTION_SECTIONS = NETWORK_CONSTITUTION_LOCALES.en.sections;
export function getNetworkConstitution(language: string): NetworkCharter {
  return NETWORK_CONSTITUTION_LOCALES[language.split(/[-_]/)[0]] ?? NETWORK_CONSTITUTION_LOCALES.en;
}
